const: Readonly<{
    /** The chip itself. Every chip carries this, whatever it is for. */
    block: "mdy-chip";
    /** An option in single-select mode: it reserves the room its tick will need. */
    centered: "mdy-chip--centered";
    /** An option that can be taken several times: a label between two step buttons. */
    counter: "mdy-chip--counter";
    /** A value already taken, shown on the control rather than offered in the list. */
    value: "mdy-chip--value";
    /** Taken. The state a theme paints; it applies in either mode. */
    selected: "mdy-chip--selected";
    /** Carries a control for taking the value off again, which changes the room the label has. */
    removable: "mdy-chip--removable";
    /** The tick. Drawn by the theme when a renderer supplies no icon of its own. */
    check: "mdy-chip__check";
    /** The chip's text. */
    label: "mdy-chip__label";
    /** How many times this option has been taken, in counter mode. */
    count: "mdy-chip__count";
    /** A step button — one down, one up. */
    step: "mdy-chip__btn";
    /** The control that takes a chosen value off, on the chip standing for it. */
    remove: "mdy-chip__remove";
    /**
     * The controls that move a chosen value one place, on the chip standing for it.
     *
     * A pointer path that is **not** a drag. WCAG 2.5.7 asks for one independently of any keyboard
     * path: somebody using a pointer who cannot hold and drag — a tremor, a head pointer, a switch —
     * has no way to reorder otherwise, and a keyboard alternative does not discharge it. Drawn only
     * where the field asked to be reorderable, so a set of filters gains no furniture.
     */
    move: "mdy-chip__move";
    /** Wraps a chip a renderer did not draw itself, so a custom option still sits in the grid. */
    wrapper: "mdy-chip-wrapper";
}>

widgets:MDY_CSS_PROPERTIES:
const: Readonly<{
    /**
     * Written by `anchorOverlay`, read by `.mdy-overlay` in the foundation. The whole placement
     * decision reaches the page through these eight and nothing else.
     */
    overlay: Readonly<{
        top: "--mdy-overlay-top";
        bottom: "--mdy-overlay-bottom";
        left: "--mdy-overlay-left";
        right: "--mdy-overlay-right";
        /** Set only when the popup matches its anchor's width, as a select's list does. */
        width: "--mdy-overlay-width";
        /** Always set: it is what stops a content-sized popup running off the side of the screen. */
        maxWidth: "--mdy-overlay-max-width";
        /** Always set: the room on the side the popup was given, so a long list scrolls rather than
         * overflowing the viewport. */
        maxHeight: "--mdy-overlay-max-height";
        /** `none` when anchored, a centring translate when the popup gave up on its anchor. */
        transform: "--mdy-overlay-transform";
    }>;
    /** Written by `layoutNodeAttributes` on a columns row; the foundation divides the row by it. */
    layout: Readonly<{
        columnCount: "--mdy-layout-column-count";
        /** Which track a column starts in, when a slot places itself rather than following row order. */
        columnStart: "--mdy-layout-column-start";
        /** Whether a column shows. Written as a `display` value so the cascade needs no extra selector. */
        columnDisplay: "--mdy-layout-column-display";
    }>;
    /** Written per control, where a theme needs a number only the renderer knows. */
    control: Readonly<{
        /**
         * How far along the slider's value sits, as a **unitless ratio in 0–1** — not a percentage.
         *
         * The stylesheet has to place the stop at `thumb/2 + ratio * (100% - thumb)`, because a range
         * input's handle travels by its centre and never hangs off either end. That needs the ratio as
